#!/usr/bin/env python3
"""Fetch a maven artifact + transitive deps from repo1.maven.org (via proxy) into a local maven2 mirror."""
import os, sys, re, urllib.request, xml.etree.ElementTree as ET

MIRROR = "/opt/opencode/m2mirror"
REPO1 = "https://repo1.maven.org/maven2"
VN = "http://maven.apache.org/POM/4.0.0"
QUEUE = []
DONE = set()

def http(url):
    req = urllib.request.Request(url)
    return urllib.request.urlopen(req, timeout=30).read()

def get(url):
    try:
        return http(url)
    except urllib.error.HTTPError as e:
        return None

def fetch_file(g, a, v, ext):
    d = os.path.join(MIRROR, *g.split("."), a, v)
    os.makedirs(d, exist_ok=True)
    f = os.path.join(d, f"{a}-{v}.{ext}")
    if os.path.exists(f) and os.path.getsize(f) > 0:
        return True
    data = get(f"{REPO1}/{'/'.join(g.split('.'))}/{a}/{v}/{a}-{v}.{ext}")
    if data is None:
        return False
    open(f, "wb").write(data)
    return True

def enqueue(g, a, v):
    key = (g, a, v)
    if key not in DONE:
        DONE.add(key)
        QUEUE.append(key)

def process(g, a, v):
    d = os.path.join(MIRROR, *g.split("."), a, v)
    os.makedirs(d, exist_ok=True)
    # pom
    if not fetch_file(g, a, v, "pom"):
        print(f"  !! no pom {g}:{a}:{v}")
        return
    if not fetch_file(g, a, v, "jar"):
        print(f"  !! no jar {g}:{a}:{v}")
    # parse deps
    pom = os.path.join(d, f"{a}-{v}.pom")
    try:
        tree = ET.parse(pom)
    except ET.ParseError as e:
        return
    root = tree.getroot()
    # parent
    parent = root.find(f"{{{VN}}}parent")
    if parent is not None:
        pg = parent.findtext(f"{{{VN}}}groupId")
        pa = parent.findtext(f"{{{VN}}}artifactId")
        pv = parent.findtext(f"{{{VN}}}version")
        if pg and pa and pv:
            enqueue(pg.strip(), pa.strip(), pv.strip())
    if v == "4.11.0.201803080745-r" and a == "org.eclipse.jgit":
        # handle properties in this pom
        props = {}
        for p in root.find(f"{{{VN}}}properties") or []:
            tag = p.tag.split("}")[-1]
            props[tag] = p.text or ""
    for dep in root.findall(f".//{{{VN}}}dependency"):
        scope = dep.findtext(f"{{{VN}}}scope") or "compile"
        optional = dep.findtext(f"{{{VN}}}optional") or "false"
        if scope not in ("compile", "runtime") or optional.strip().lower() == "true":
            continue
        dg = dep.findtext(f"{{{VN}}}groupId")
        da = dep.findtext(f"{{{VN}}}artifactId")
        dv = dep.findtext(f"{{{VN}}}version")
        if not (dg and da and dv):
            continue
        dg, da, dv = dg.strip(), da.strip(), dv.strip()
        if "${" in dv:
            dv = re.sub(r"\$\{([^}]*)\}", lambda m: props.get(m.group(1), m.group(0)), dv)
        enqueue(dg, da, dv)

