#!/usr/bin/env python3
"""Fetch a maven artifact + transitive deps from repo1.maven.org (via proxy) into a local maven2 mirror."""
import os, re, sys, time, urllib.request, xml.etree.ElementTree as ET

MIRROR = "/opt/opencode/m2mirror"
REPO1 = "https://repo1.maven.org/maven2"
VN = "http://maven.apache.org/POM/4.0.0"
QUEUE = []
DONE = set()

def get(url):
    for attempt in range(8):
        try:
            return urllib.request.urlopen(url, timeout=15).read()
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return None
            time.sleep(2)
        except Exception:
            time.sleep(2)
    return None

def list_dir(url):
    d = get(url)
    if d is None:
        return None
    return re.findall(r'href="([^"]+)"', d.decode(errors="replace"))

def fetch_rel(g, a, v, ext, label):
    dirp = os.path.join(MIRROR, *g.split("."), a, v)
    os.makedirs(dirp, exist_ok=True)
    # candidate filename
    cand = f"{a}-{v}.{ext}"
    path = os.path.join(dirp, cand)
    if os.path.exists(path) and os.path.getsize(path) > 0:
        return True
    # discover real file name via listing
    found = None
    files = list_dir(f"{REPO1}/{'/'.join(g.split('.'))}/{a}/{v}/")
    if files:
        for f in files:
            if f.endswith(f"-{v}.{ext}") and not f.startswith(".") :
                found = f
                break
    if found and found != cand:
        path = os.path.join(dirp, found)
        if os.path.exists(path) and os.path.getsize(path) > 0:
            return True
    target = found or cand
    rel = f"{'/'.join(g.split('.'))}/{a}/{v}/{target}"
    data = get(REPO1 + "/" + rel)
    if data is None:
        print(f"  !! FAIL {label} {'/'.join(g.split('.'))}/{a}/{v}/{target}", flush=True)
        return False
    open(os.path.join(dirp, target), "wb").write(data)
    print(f"  + {label} {a}/{v}/{target}", flush=True)
    return True

def enqueue(g, a, v):
    key = (g, a, v)
    if not any(k == key for k in DONE):
        DONE.add(key)
        QUEUE.append(key)

def process(g, a, v, label=""):
    if not fetch_rel(g, a, v, "pom", label):
        return
    pom_path = os.path.join(MIRROR, *g.split("."), a, v)
    pom_file = None
    for f in os.listdir(pom_path):
        if f.endswith(".pom") and not f.startswith("."):
            pom_file = f
            break
    root = ET.parse(os.path.join(pom_path, pom_file)).getroot()
    parent = root.find(f"{{{VN}}}parent")
    if parent is not None:
        pg = parent.findtext(f"{{{VN}}}groupId")
        pa = parent.findtext(f"{{{VN}}}artifactId")
        pv = parent.findtext(f"{{{VN}}}version")
        if pg and pa and pv:
