        targets = [tuple(line.strip().split(":")) for line in fh if line.strip() and not line.startswith("#")]
    for t in targets:
        enqueue(*t)
    i = 0
    while i < len(QUEUE):
        g, a, v = QUEUE[i]
        i += 1
        process(g, a, v, "" if any(a == t[1] and v == t[2] and g == t[0] for t in targets) else "")
        print(f"[{i}/{len(QUEUE)}] done {g}:{a}:{v}", flush=True)

