import scala.quoted._

case class FirstArg(firstArgName: String, firstArgValue: Int)

object FirstArg {

  implicit inline def firstArg: FirstArg = ${ impl }

  def impl(given qctx: QuoteContext): Expr[FirstArg] = {
    import qctx.tasty.{_, given}

    def enclosingClass(sym: Symbol): Symbol =
      if (sym.isClassDef) sym
      else enclosingClass(sym.owner)

    val cls = enclosingClass(rootContext.owner)

    def firstParamName: String = cls.tree match {
      case cdef: ClassDef => cdef.constructor.paramss.head.head.name
      case _ => throw new IllegalStateException("Expected a class definition")
    }

    val name = firstParamName
    val value = Select.unique(This(cls), name).seal.cast[Int]

    '{ FirstArg(${Expr(name)}, $value) }
  }
}import FirstArg._

class Foo(val first: Int, val second: Int, val third: Int) {
  def foo(implicit fa: FirstArg): (String, Int) = (fa.firstArgName, fa.firstArgValue)

  val firstArgInfo: (String, Int) = foo
}

